/**
 * Decoder and sampler for the empirical landmark-noise model
 * (noise-model.data.ts, generated by scripts/research/noise-model.py).
 */
import { NOISE_COMPONENTS, NOISE_DATA_B64, NOISE_RESIDUAL_B64, NOISE_RESIDUAL_SCALE, NOISE_SCALES } from "./noise-model.data";

const N = 478 * 3;

function decodeInt16(b64: string): Int16Array {
  const bin = globalThis.atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Int16Array(bytes.buffer, bytes.byteOffset, bytes.byteLength / 2);
}

let cache: { comps: Float64Array[]; resid: Float64Array } | null = null;

/** Components (each 478 × xyz, IPD units) and the per-coordinate residual σ. */
export function noiseModel(): { comps: Float64Array[]; resid: Float64Array } {
  if (cache) return cache;
  const q = decodeInt16(NOISE_DATA_B64);
  const comps: Float64Array[] = [];
  for (let k = 0; k < NOISE_COMPONENTS; k++) {
    const c = new Float64Array(N);
    for (let i = 0; i < N; i++) c[i] = q[k * N + i] * NOISE_SCALES[k];
    comps.push(c);
  }
  const rq = decodeInt16(NOISE_RESIDUAL_B64);
  const resid = new Float64Array(N);
  for (let i = 0; i < N; i++) resid[i] = rq[i] * NOISE_RESIDUAL_SCALE;
  cache = { comps, resid };
  return cache;
}

/** Marginal σ per landmark and axis implied by the model (IPD units, length 478 × 3). */
export function noiseMarginalSigma(): Float64Array {
  const { comps, resid } = noiseModel();
  const out = new Float64Array(N);
  for (let i = 0; i < N; i++) {
    let v = resid[i] ** 2;
    for (const c of comps) v += c[i] ** 2;
    out[i] = Math.sqrt(v);
  }
  return out;
}

/**
 * One correlated noise field (IPD units, 478 × xyz) in the upright face frame,
 * rotated by `rollRad` into the image frame.
 */
export function sampleNoiseField(gauss: () => number, rollRad = 0): Float64Array {
  const { comps, resid } = noiseModel();
  const f = new Float64Array(N);
  for (const c of comps) {
    const z = gauss();
    for (let i = 0; i < N; i++) f[i] += z * c[i];
  }
  for (let i = 0; i < N; i++) f[i] += gauss() * resid[i];
  if (rollRad !== 0) {
    const co = Math.cos(rollRad);
    const si = Math.sin(rollRad);
    for (let p = 0; p < 478; p++) {
      const x = f[3 * p];
      const y = f[3 * p + 1];
      f[3 * p] = co * x - si * y;
      f[3 * p + 1] = si * x + co * y;
    }
  }
  return f;
}
